// Copies Cesium's static runtime assets into public/cesium (not committed; regenerated by npm run prepare-cesium).
import { cpSync, mkdirSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const src = resolve(root, "node_modules/cesium/Build/Cesium");
const dst = resolve(root, "public/cesium");
if (!existsSync(src)) {
  console.error("cesium not installed; run npm install");
  process.exit(1);
}
mkdirSync(dst, { recursive: true });
for (const d of ["Workers", "ThirdParty", "Assets", "Widgets"]) cpSync(resolve(src, d), resolve(dst, d), { recursive: true });
